using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Services;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class AssetTests
{
 class User(int employee=1,bool hr=true):ICurrentUser{public string Email=>"assets@example.local";public int? EmployeeId=>employee;public int UserId=>1;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>hr;public bool Can(string p)=>hr;}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static AssetService S(AppDbContext d,User? u=null){u??=new();var c=new AppClock(TimeProvider.System);return new(d,u,c,new AuditService(d,u,c));}
 [Fact]public async Task AssignmentReturnAndMaintenanceRetainEvidence(){await using var d=await Db();await S(d).RegisterAsync("demo-01","Fictional laptop","SN-DEMO","New");var a=await d.Set<CompanyAsset>().SingleAsync();await S(d).MoveAsync(a.Id,"Assign",6,null,"New","Signed fictional receipt");Assert.Equal(6,a.AssignedEmployeeId);await Assert.ThrowsAsync<DomainException>(()=>S(d).MoveAsync(a.Id,"Assign",7,null,"Good","Duplicate"));await Assert.ThrowsAsync<DomainException>(()=>S(d).MoveAsync(a.Id,"Return",7,null,"Good","Wrong holder"));await S(d).MoveAsync(a.Id,"Return",6,null,"Scratched","Return receipt");Assert.Null((await d.Set<CompanyAsset>().SingleAsync()).AssignedEmployeeId);await S(d).MoveAsync(a.Id,"Maintenance",null,null,"Scratched","Repair ticket");await Assert.ThrowsAsync<DomainException>(()=>S(d).MoveAsync(a.Id,"Assign",6,null,"Good","Unavailable"));await S(d).MoveAsync(a.Id,"Release",null,null,"Repaired","Repair receipt");Assert.Equal("Available",(await d.Set<CompanyAsset>().SingleAsync()).Status);Assert.Equal(5,await d.Set<AssetMovement>().CountAsync());Assert.Equal(2,(await S(d,new(6,false)).GetAsync(6)).History.Count);}
 [Fact]public async Task AssetAccessIsEmployeeOrHrAndChangesRequireHr(){await using var d=await Db();await S(d).RegisterAsync("A","Demo","","New");var a=await d.Set<CompanyAsset>().SingleAsync();await S(d).MoveAsync(a.Id,"Assign",6,null,"Good","Receipt");Assert.Single((await S(d,new(6,false)).GetAsync(6)).Assets);await Assert.ThrowsAsync<DomainException>(()=>S(d,new(7,false)).GetAsync(6));await Assert.ThrowsAsync<DomainException>(()=>S(d,new(6,false)).MoveAsync(a.Id,"Return",6,null,"Good","Receipt"));await Assert.ThrowsAsync<DomainException>(()=>S(d,new(6,false)).InventoryAsync());}
 [Fact]public async Task DuplicateTagsAndMissingEvidenceDoNotMutate(){await using var d=await Db();await S(d).RegisterAsync("a","Demo","","New");await Assert.ThrowsAsync<DomainException>(()=>S(d).RegisterAsync("A","Duplicate","","New"));var a=await d.Set<CompanyAsset>().SingleAsync();await Assert.ThrowsAsync<DomainException>(()=>S(d).MoveAsync(a.Id,"Assign",6,null,"Good",""));Assert.Equal("Available",(await d.Set<CompanyAsset>().SingleAsync()).Status);Assert.Single(await d.Set<AssetMovement>().ToListAsync());}
 [Fact]public async Task MovementEvidenceCannotBeEdited(){await using var d=await Db();await S(d).RegisterAsync("a","Demo","","New");var m=await d.Set<AssetMovement>().SingleAsync();m.Evidence="Rewrite";await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveChangesAsync());}
}
